import{_ as s,o as i,c as t,ak as n}from"./chunks/framework.DKi5cyCJ.js";const u=JSON.parse('{"title":"SVN → GitLab · 04 切换（Cutover）","description":"SVN→Git 切换：冻结写、只读保留、通知同事、补推末次变更与回滚说明。 在 SVN 迁 Git 第 4 步、svn-to-git-04、截止切换、SVN 只读时使用。","frontmatter":{"name":"svn-to-git-04-cutover","description":"SVN→Git 切换：冻结写、只读保留、通知同事、补推末次变更与回滚说明。 在 SVN 迁 Git 第 4 步、svn-to-git-04、截止切换、SVN 只读时使用。"},"headers":[],"relativePath":"docs/assets/attachments/gitlab-skills/svn-to-git-04-cutover/SKILL.md","filePath":"docs/assets/attachments/gitlab-skills/svn-to-git-04-cutover/SKILL.md"}'),l={name:"docs/assets/attachments/gitlab-skills/svn-to-git-04-cutover/SKILL.md"};function e(o,a,p,h,r,c){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="svn-→-gitlab-·-04-切换-cutover" tabindex="-1">SVN → GitLab · 04 切换（Cutover） <a class="header-anchor" href="#svn-→-gitlab-·-04-切换-cutover" aria-label="Permalink to &quot;SVN → GitLab · 04 切换（Cutover）&quot;">​</a></h1><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h2><ul><li>至少试迁仓 03 验收通过；批量仓已 push 或已排期。</li><li>策略 <strong>C1</strong>：不做长期双写。</li><li>变量：项目清单、<code>SVN_URL</code> 列表、GitLab 路径列表。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-切换前末次同步-每个仓" tabindex="-1">1) 切换前末次同步（每个仓） <a class="header-anchor" href="#_1-切换前末次同步-每个仓" aria-label="Permalink to &quot;1) 切换前末次同步（每个仓）&quot;">​</a></h3><p>若 SVN 在迁后仍有提交：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /d </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%WORK_ROOT%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\\</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">%LOCAL_DIR%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git svn fetch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git checkout main</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git svn rebase</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git push origin --all</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git push origin --tags</span></span></code></pre></div><p>确认无人再向 SVN 写入后再做 §2。</p><h3 id="_2-svn-只读" tabindex="-1">2) SVN 只读 <a class="header-anchor" href="#_2-svn-只读" aria-label="Permalink to &quot;2) SVN 只读&quot;">​</a></h3><p>与 SVN 管理员约定生效时刻，任选其一并记录：</p><ul><li>路径级 authz 改为只读</li><li>收回写账号 / 只留只读账号</li><li>停用写服务（仍保留只读或备份）</li></ul><p><strong>建议只读保留 ≥ 6 个月</strong>后再谈归档下线。</p><h3 id="_3-通知同事-模板" tabindex="-1">3) 通知同事（模板） <a class="header-anchor" href="#_3-通知同事-模板" aria-label="Permalink to &quot;3) 通知同事（模板）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主题：【仓库切换】&lt;项目名&gt; 自 &lt;日期时间&gt; 起改用 GitLab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 新地址：http://192.168.1.173/&lt;GROUP&gt;/&lt;PROJECT&gt;</span></span>
<span class="line"><span>2. 克隆：先开 git_http_tunnel.bat，再</span></span>
<span class="line"><span>   git clone http://127.0.0.1:18173/&lt;GROUP&gt;/&lt;PROJECT&gt;.git</span></span>
<span class="line"><span>3. 认证：用户名 oauth2，密码用 Personal Access Token</span></span>
<span class="line"><span>4. 默认分支：main；请推 feature/* 再提 MR</span></span>
<span class="line"><span>5. SVN 自该时刻起只读，勿再提交</span></span></code></pre></div><p>附：《2.GitLab部署操作命令手册》§7。</p><h3 id="_4-文档与周边" tabindex="-1">4) 文档与周边 <a class="header-anchor" href="#_4-文档与周边" aria-label="Permalink to &quot;4) 文档与周边&quot;">​</a></h3><ul><li>[ ] 设计/发布文档中的 SVN URL 改为 GitLab</li><li>[ ] 构建机/脚本 checkout 地址已改</li><li>[ ] Issue/看板说明已更新</li></ul><h3 id="_5-回滚说明-仅紧急" tabindex="-1">5) 回滚说明（仅紧急） <a class="header-anchor" href="#_5-回滚说明-仅紧急" aria-label="Permalink to &quot;5) 回滚说明（仅紧急）&quot;">​</a></h3><p>若 Git 侧不可用且必须临时写回：</p><ol><li>恢复 SVN 写权限（仅紧急窗口）</li><li>修复 GitLab/网络后再次 <code>git svn fetch</code> + push，或从 Git 导出补丁回 SVN（需人工评审）</li><li><strong>禁止</strong>长期双向提交</li></ol><p>本 Skill <strong>不自动</strong>改 SVN 服务端权限；只产出清单与提醒，由有权限的人执行。</p><h2 id="完成门槛" tabindex="-1">完成门槛 <a class="header-anchor" href="#完成门槛" aria-label="Permalink to &quot;完成门槛&quot;">​</a></h2><ul><li>[ ] 末次同步已做或确认无新 SVN 提交</li><li>[ ] SVN 只读已执行或有明确延期日期与责任人</li><li>[ ] 同事通知已发出（或草稿已交用户发送）</li><li>[ ] 文档/脚本 URL 已改或已列待改项</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>迁移批次结束。后续大文件清理、CI、HTTPS 另开任务。<br> 若还有未迁清单项 → 回到 <code>svn-to-git-01-inventory</code>。</p>`,25)])])}const g=s(l,[["render",e]]);export{u as __pageData,g as default};
